//! Generated by `scripts/gen_benches.py`: times `lean_runtime::semantics::float32::of_bits`; the
//! native twin is `benches/native/Bench/Float32OfBits.lean`.
//! one operand in eight has all exponent bits set

#![allow(unused_parens, unused_imports, unused_variables, unused_mut)]
#![allow(
    clippy::double_parens,
    clippy::unnecessary_cast,
    clippy::redundant_closure
)]
#![allow(clippy::identity_op, clippy::let_and_return)]

use lean_runtime::semantics::float32;
use lean_runtime_bench::*;
use std::hint::black_box;

#[inline(never)]
fn kernel(inp: &(), n: u64) -> u64 {
    let (mut x, mut acc) = (SEED, 0u64);
    for _ in 0..n {
        x = step(x);
        acc = mix(
            acc,
            gbits(float32::of_bits({
                let b = (x >> 32) as u32;
                if x & 7 == 0 {
                    b | 0x7F80_0000
                } else {
                    b
                }
            })),
        );
    }
    acc
}

fn main() {
    run(|| (), kernel)
}
